<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];if(isset($_GET['mark'])){$now=time();$stmt=$db->prepare('UPDATE notifications SET read_at=COALESCE(read_at,?) WHERE owner_id=?');$stmt->bind_param('ii',$now,$uid);$stmt->execute();$stmt->close();}$rows=[];$stmt=$db->prepare('SELECT * FROM notifications WHERE owner_id=? ORDER BY created_at DESC LIMIT 100');$stmt->bind_param('i',$uid);$stmt->execute();$r=$stmt->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$stmt->close();pv_page_start('Notifications','notifications.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('notifications.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">ACCOUNT SIGNALS</span><h1>Notifications</h1><p class="pv-subtle">Materialization, community, exchange and arena notifications.</p></div><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url('notifications.php?mark=1'))?>">Mark all read</a></div><section class="pv-card" style="padding:18px"><?php foreach($rows as $n):?><article class="pv-news-item <?=($n['read_at']===null)?'unread':''?>"><small><?=pv_h(strtoupper((string)$n['category']))?> · <?=date('Y-m-d H:i',(int)$n['created_at'])?></small><h3><?=pv_h((string)$n['title'])?></h3><p><?=pv_h((string)$n['body'])?></p><?php if((string)$n['link']!==''):?><a class="pv-button pv-button-secondary" href="<?=pv_h(pv_url((string)$n['link']))?>">Open</a><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><div class="pv-empty">No notifications.</div><?php endif;?></section></section></main></div><?php pv_page_end(); ?>
